} else {
crm_err("fcntl() read failed");
close(csock);
return TRUE;
}

session = create_psk_tls_session(csock, GNUTLS_SERVER, psk_cred_s);
if (session == NULL) {
crm_err("TLS session creation failed");
close(csock);
return TRUE;
}

new_client = calloc(1, sizeof(crm_client_t));
